/**
 * The flagship hand-authored narrated scene: **elastic vs inelastic
 * collisions**, for the prepared Physics demo chapter
 * (`src/lib/demo/collisions.ts`).
 *
 * Zero model calls. Zero generated bytes. This is what ships first, and it is
 * a complete lesson with the voice bus at zero: visual, caption, transport,
 * one real checkpoint, a remedial detour that re-converges, and a transcript.
 *
 * ### Authoring rules applied here
 *
 *  - **Under ~25 words a line.** One line is one clip, one cache entry, one
 *    interruptible unit, and about the longest stretch of uninterrupted
 *    speech a 15-year-old tolerates over a diagram.
 *  - **Numbers are spoken as words** ("twelve divided by three"), because the
 *    digits are already on screen in the diagram. Speech carries the
 *    reasoning; the picture carries the data.
 *  - **Second person, present tense, declarative. No praise.** "You kept the
 *    sign" beats "great job" — it is specific, true, and survives repetition.
 *    `lintSceneScripts` enforces the blocklist.
 *  - **The checkpoint is where the teaching lands**, not an interruption
 *    bolted onto it: the student predicts the common velocity *before* the
 *    diagram shows it, and the remedial branch names the actual mistake
 *    (reading a momentum as a speed) instead of restating the answer louder.
 *
 * Every number below is recomputed on screen: `CollisionDiagram` derives the
 * final velocities from `(m1, m2, u1, u2, e)` via `collide1D` and never takes
 * them from this file (`src/components/viz/collision-diagram.tsx:21-28`). The
 * captions and the diagram therefore cannot disagree — if a caption here were
 * wrong, the diagram would contradict it rather than echo it.
 */
import type { VisualSpec } from "@/lib/types";
import { assertValidScene } from "./scene";
import { defineScene, type NarratedScene } from "./types";

/** The spine of the lesson: 2 kg of clay at 6 m/s into 1 kg at rest. */
const CLAY: VisualSpec = {
  kind: "collision-1d",
  title: "Clay lumps: 2 kg into 1 kg",
  m1: 2,
  m2: 1,
  u1: 6,
  u2: 0,
  e: 0,
  label1: "2 kg",
  label2: "1 kg",
  massUnit: "kg",
  velocityUnit: "m/s",
  symbolic: false,
};

/** Equal masses, perfectly elastic, written symbolically so it is a *rule*. */
const EQUAL_ELASTIC: VisualSpec = {
  kind: "collision-1d",
  title: "Equal masses, perfectly elastic",
  m1: 1,
  m2: 1,
  u1: 1,
  u2: 0,
  e: 1,
  label1: "A",
  label2: "B",
  massUnit: "m",
  velocityUnit: "u",
  symbolic: true,
};

const BARS_BEFORE: VisualSpec = {
  kind: "momentum-bars",
  title: "Momentum before the collision",
  items: [
    { label: "2 kg lump", value: 12, unit: "kg·m/s" },
    { label: "1 kg lump", value: 0, unit: "kg·m/s" },
    { label: "Total", value: 12, unit: "kg·m/s" },
  ],
};

const BARS_AFTER: VisualSpec = {
  kind: "momentum-bars",
  title: "Momentum after they stick",
  items: [
    { label: "3 kg together", value: 12, unit: "kg·m/s" },
    { label: "Total", value: 12, unit: "kg·m/s" },
  ],
};

const CONSERVATION = { conceptId: "demo-c-conservation", conceptTitle: "Conservation of momentum" };
const ELASTIC = { conceptId: "demo-c-elastic", conceptTitle: "Elastic collisions" };
const INELASTIC = { conceptId: "demo-c-inelastic", conceptTitle: "Inelastic collisions" };

/**
 * The scene. Exported already parsed and structurally validated, so an
 * authoring mistake is an import-time failure in tests rather than a dead
 * transport bar in front of a student.
 */
export const DEMO_COLLISION_SCENE: NarratedScene = assertValidScene(
  defineScene({
    id: "scene__demo-collisions__elastic-vs-inelastic",
    questId: "demo-collisions",
    conceptId: "demo-c-inelastic",
    title: "Elastic or inelastic: what survives a crash",
    subtitle: "Two lumps of clay, one rule that always holds and one that does not.",
    subject: "Physics",
    origin: "demo_prepared",
    visual: CLAY,
    chapters: [
      { id: "ch-survives", title: "What survives a crash", conceptId: CONSERVATION.conceptId, cueId: "open" },
      { id: "ch-elastic", title: "Elastic: nothing lost", conceptId: ELASTIC.conceptId, cueId: "elastic-setup" },
      { id: "ch-inelastic", title: "Inelastic: they stick", conceptId: INELASTIC.conceptId, cueId: "inelastic-setup" },
    ],
    cues: [
      /* ---- Chapter 1: the one difference that matters ---- */
      {
        kind: "narration",
        id: "open",
        ...CONSERVATION,
        text: "Two things hit. Momentum always survives the hit. Kinetic energy sometimes does not. That one difference is this whole lesson.",
        visual: { mode: "before", visual: CLAY },
        readMs: 7600,
      },
      {
        kind: "narration",
        id: "before-bars",
        ...CONSERVATION,
        text: "Before the crash: two kilograms at six metres per second, plus nothing. Twelve kilogram metres per second, to the right.",
        visual: { mode: "full", visual: BARS_BEFORE, highlight: "total" },
        readMs: 7600,
      },
      {
        kind: "narration",
        id: "sign-rule",
        ...CONSERVATION,
        text: "Right is positive, left is negative. Momentum carries the sign, so a left-moving mass subtracts. Speeds alone will mislead you.",
        visual: { mode: "full", visual: BARS_BEFORE },
        readMs: 7800,
      },

      /* ---- Chapter 2: elastic, stated as a rule ---- */
      {
        kind: "narration",
        id: "elastic-setup",
        ...ELASTIC,
        text: "Equal masses, perfectly elastic. A arrives at speed u, B waits. Both momentum and kinetic energy must come out unchanged.",
        visual: { mode: "before", visual: EQUAL_ELASTIC },
        readMs: 7600,
      },
      {
        kind: "narration",
        id: "elastic-result",
        ...ELASTIC,
        text: "Only one outcome satisfies both laws: they swap. A stops dead and B leaves at speed u.",
        visual: { mode: "full", visual: EQUAL_ELASTIC, highlight: "v2" },
        readMs: 6600,
      },
      {
        kind: "narration",
        id: "elastic-e",
        ...ELASTIC,
        text: "Nothing was lost. e equals one means they separate exactly as fast as they approached, so the kinetic energy total holds.",
        visual: { mode: "full", visual: EQUAL_ELASTIC, highlight: "ke" },
        readMs: 7800,
      },

      /* ---- Chapter 3: inelastic, with the prediction first ---- */
      {
        kind: "narration",
        id: "inelastic-setup",
        ...INELASTIC,
        text: "Now they stick together. Two kilograms at six metres per second meets one kilogram at rest. The same twelve to share.",
        visual: { mode: "before", visual: CLAY },
        readMs: 7800,
      },
      {
        kind: "checkpoint",
        id: "checkpoint-common-v",
        ...INELASTIC,
        text: "Your turn. Work it out before the diagram shows you.",
        visual: { mode: "before", visual: CLAY },
        prompt: {
          // The real demo question, so the server scores it against the
          // stored key exactly as it would at a track checkpoint.
          questionId: "demo-q07",
          text: "A 2 kg lump of clay moving at 6 m/s hits and sticks to a 1 kg lump of clay at rest. What is their common velocity just after the collision?",
          options: [
            { id: "A", text: "6.0 m/s" },
            { id: "B", text: "3.0 m/s" },
            { id: "C", text: "12 m/s" },
            { id: "D", text: "4.0 m/s" },
          ],
          hint: "Total momentum before equals total momentum after, and after the collision there is one 3 kg object.",
        },
        branch: { correct: "stick-result", wrong: "fix-momentum-is-not-speed" },
      },
      {
        kind: "narration",
        id: "stick-result",
        ...INELASTIC,
        text: "Three kilograms now carries the twelve. Twelve divided by three is four metres per second, in the original direction.",
        visual: { mode: "full", visual: CLAY, highlight: "v" },
        readMs: 7400,
      },
      {
        kind: "narration",
        id: "after-bars",
        ...INELASTIC,
        text: "Before, twelve. After, twelve. The bar length did not change. That is conservation, and it is not a coincidence.",
        visual: { mode: "full", visual: BARS_AFTER, highlight: "total" },
        readMs: 7200,
      },
      {
        kind: "narration",
        id: "ke-loss",
        ...INELASTIC,
        text: "Kinetic energy fell from thirty-six joules to twenty-four. Twelve joules went into heat, sound and permanently dented clay.",
        visual: { mode: "full", visual: CLAY, highlight: "ke" },
        readMs: 7600,
      },
      {
        kind: "narration",
        id: "verdict",
        ...INELASTIC,
        text: "Momentum conserved, kinetic energy not: that is inelastic. Elastic keeps both. The value of e tells you which one you are in.",
        visual: { mode: "full", visual: CLAY },
        readMs: 8200,
        terminal: true,
      },

      /* ----------------------------------------------------------------
       * The remedial detour.
       *
       * Reached only by a wrong answer, and written in the simplified
       * register: slower, one idea per line, and it names the mistake rather
       * than repeating the result. It re-converges on `after-bars`, so a
       * wrong answer costs a detour and never an exit.
       * ---------------------------------------------------------------- */
      {
        kind: "narration",
        id: "fix-momentum-is-not-speed",
        ...INELASTIC,
        text: "Slow down. Twelve is the momentum, not the speed. Momentum is mass times velocity, so divide the mass back out.",
        visual: { mode: "full", visual: BARS_BEFORE, highlight: "total" },
        readMs: 7600,
        remedial: true,
      },
      {
        kind: "narration",
        id: "fix-total-mass",
        ...INELASTIC,
        text: "After they stick there is one object, and its mass is three kilograms. Not two, and not an average of the two.",
        visual: { mode: "before", visual: CLAY, highlight: "m" },
        readMs: 7400,
        remedial: true,
      },
      {
        kind: "narration",
        id: "fix-divide",
        ...INELASTIC,
        text: "Twelve kilogram metres per second over three kilograms is four metres per second. Averaging six and zero ignores the masses.",
        visual: { mode: "full", visual: CLAY, highlight: "v" },
        readMs: 7800,
        remedial: true,
        goto: "after-bars",
      },
    ],
  }),
);

/** Scenes the client can play with no server call at all. */
export const DEMO_SCENES: readonly NarratedScene[] = [DEMO_COLLISION_SCENE];

export function findDemoScene(id: string): NarratedScene | null {
  return DEMO_SCENES.find((s) => s.id === id) ?? null;
}
